"""Source-bound bridge approach and crossing observations for NRS 484B.633(2).

This module reports physical measurements and document provenance. It does not
decide whether a structure or a driver's speed is legally safe.
"""

from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path
import re


FEET_PER_METRE = 3.280839895013123
CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


def _finite(value, label):
    if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(value):
        raise ValueError(f"finite {label} required")
    return float(value)


def read_bound_json(path: Path, expected_sha256: str) -> dict:
    path = Path(path)
    if not path.is_file() or path.is_symlink():
        raise ValueError(f"original source missing: {path.name}")
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError(f"original source hash differs: {path.name}")
    value = json.loads(raw)
    if not isinstance(value, dict):
        raise ValueError(f"original source object required: {path.name}")
    return value


def verify_site_bundle(path: Path, expected_sha256: str, case_id: str) -> dict:
    """Verify external administrative and surveyed sources, without executing them."""
    path = Path(path)
    if path.is_symlink():
        raise ValueError("original bridge dossier cannot be a symlink")
    path = path.resolve()
    dossier = read_bound_json(path, expected_sha256)
    validate_site(dossier, expected_case=case_id)
    refs = [dossier["maximum_declaration_source"], dossier["stationing_source"]]
    refs.extend(dossier["authority"].values())
    for sign in dossier["signs"].values():
        refs.extend((sign["erected_source"], sign["maintained_source"]))
    for ref in refs:
        if not isinstance(ref, dict) or not isinstance(ref.get("path"), str) or not re.fullmatch(
                r"[0-9a-f]{64}", str(ref.get("sha256", ""))):
            raise ValueError("source-hashed original administrative/survey record required")
        source = path.parent / ref["path"]
        if source.is_symlink() or not source.is_file() or path.parent not in source.resolve().parents:
            raise ValueError("original bridge dossier source missing or outside bundle")
        if hashlib.sha256(source.read_bytes()).hexdigest() != ref["sha256"]:
            raise ValueError("original bridge dossier source hash differs")
    return dossier


def validate_site(dossier: dict, *, expected_case: str | None = None) -> dict:
    """Require a reviewed original dossier for both approaches and Department act.

    Stations are original road-centreline metres increasing from end A to end B.
    End A's sign is before A in the positive direction; end B's sign is beyond B
    in the negative direction. The 100-foot measure is reported, not rounded into
    a fabricated placement tolerance.
    """
    if not isinstance(dossier, dict):
        raise ValueError("original site dossier required")
    if dossier.get("format") != "worker-bridge-site-v1":
        raise ValueError("bridge site dossier format differs")
    if expected_case is not None and dossier.get("case_id") != expected_case:
        raise ValueError("bridge site case identity differs")
    if dossier.get("structure_kind") not in ("bridge", "other_elevated_structure"):
        raise ValueError("bridge or other elevated structure source required")
    a = _finite(dossier.get("end_a_station_m"), "end A station")
    b = _finite(dossier.get("end_b_station_m"), "end B station")
    if b - a < 10:
        raise ValueError("ordered distinct elevated structure ends required")
    signs = dossier.get("signs")
    if not isinstance(signs, dict) or set(signs) != {"end_a", "end_b"}:
        raise ValueError("suitable original signs before both ends required")
    for end, expected_side in (("end_a", -1), ("end_b", 1)):
        sign = signs[end]
        if not isinstance(sign, dict):
            raise ValueError(f"original {end} sign source required")
        station = _finite(sign.get("station_m"), f"{end} sign station")
        structure_end = a if end == "end_a" else b
        if (station - structure_end) * expected_side <= 0:
            raise ValueError(f"original {end} sign lies on wrong approach")
        if not sign.get("erected_source") or not sign.get("maintained_source"):
            raise ValueError(f"original {end} sign erection/maintenance sources required")
        if sign.get("face_direction") != ("toward_b" if end == "end_a" else "toward_a"):
            raise ValueError(f"original {end} sign face direction differs")
    maximum = _finite(dossier.get("declared_maximum_mph"), "declared maximum mph")
    if maximum <= 0 or not dossier.get("maximum_declaration_source"):
        raise ValueError("source-backed positive Department maximum required")
    authority = dossier.get("authority")
    required = ("chapter_408_source", "highway_source", "investigation_source",
                "finding_source", "department_decision_source", "sign_causation_source")
    if not isinstance(authority, dict) or any(not authority.get(key) for key in required):
        raise ValueError("Department chapter 408 investigation/decision chronology sources required")
    if not dossier.get("map_opendrive_sha256") or not dossier.get("stationing_source"):
        raise ValueError("original mapped highway stationing and OpenDRIVE hash required")
    offsets = {
        "end_a": (a - float(signs["end_a"]["station_m"])) * FEET_PER_METRE,
        "end_b": (float(signs["end_b"]["station_m"]) - b) * FEET_PER_METRE,
    }
    return {"end_a_station_m": a, "end_b_station_m": b,
            "sign_offsets_ft": offsets, "declared_maximum_mph": maximum,
            "structure_kind": dossier["structure_kind"]}


def measure_crossing(dossier: dict, rows: list[dict], case_id: str, *, expected_frames: int = 900) -> dict:
    site = validate_site(dossier, expected_case=case_id)
    if len(rows) != expected_frames:
        raise ValueError(f"{expected_frames} original 20 Hz frames required")
    direction = dossier.get("travel_direction")
    if direction not in ("a_to_b", "b_to_a"):
        raise ValueError("original approach direction required")
    a, b = site["end_a_station_m"], site["end_b_station_m"]
    speeds = []
    first_station = last_station = None
    crossing_frames = []
    last_original_frame = None
    first_time_s = None
    for index, row in enumerate(rows):
        if not isinstance(row, dict) or row.get("index") != index:
            raise ValueError("contiguous original frame indices required")
        frame = row.get("original_frame")
        if not isinstance(frame, int) or (last_original_frame is not None and frame != last_original_frame + 1):
            raise ValueError("contiguous original simulator frames required")
        last_original_frame = frame
        time_s = _finite(row.get("time_s"), "original time")
        if first_time_s is None:
            first_time_s = time_s
        if abs(time_s - first_time_s - index / 20) > 0.01:
            raise ValueError("original 20 Hz time join differs")
        station = _finite(row.get("ego_station_m"), "ego station")
        speed = _finite(row.get("ego_speed_mps"), "ego speed")
        if speed < 0:
            raise ValueError("negative original speed")
        if row.get("ego_actor_id") != dossier.get("ego_actor_id"):
            raise ValueError("original ego actor identity differs")
        if first_station is None:
            first_station = station
        last_station = station
        if a <= station <= b:
            crossing_frames.append(frame)
            speeds.append(speed * 2.2369362920544)
    if not crossing_frames:
        raise ValueError("no original frame on elevated structure")
    if direction == "a_to_b" and not (first_station < a and last_station > b):
        raise ValueError("original A-to-B approach and exit incomplete")
    if direction == "b_to_a" and not (first_station > b and last_station < a):
        raise ValueError("original B-to-A approach and exit incomplete")
    return {"case_id": case_id, "direction": direction,
            "structure_kind": site["structure_kind"],
            "sign_offsets_ft": site["sign_offsets_ft"],
            "declared_maximum_mph": site["declared_maximum_mph"],
            "observed_crossing_speed_mph": {"minimum": min(speeds), "maximum": max(speeds),
                                            "samples": len(speeds)},
            "crossing_original_frames": [crossing_frames[0], crossing_frames[-1]],
            "original_frame_count": len(rows),
            "speed_relative_to_declared_maximum": "measured_only_no_legal_verdict",
            "sign_placement_judgment": "unresolved",
            "structure_safety_judgment": "unresolved",
            "physical_completion": "requires_independent_original_review"}

"""Native construction seam for a reviewed elevated highway structure.

The CARLA adapter must read back mapped structure and sign geometry. This
module never substitutes a sign prop for evidence of Department authorization.
"""

from __future__ import annotations

from bridge_observations import validate_site


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")

ADAPTER_METHODS = (
    "loaded_map_sha256", "snapshot_settings", "configure_sync", "readback_sync",
    "restore_settings", "readback_restored", "read_structure_ends",
    "spawn_vehicle", "read_vehicle_class", "set_crossing_route",
    "set_target_speed_mps", "spawn_sign", "read_sign_station_and_face",
    "spawn_cameras", "tick_capture", "destroy", "actor_id",
)


def require_adapter(adapter):
    absent = [name for name in ADAPTER_METHODS if not callable(getattr(adapter, name, None))]
    if absent:
        raise ValueError("Native elevated-highway adapter methods missing: " + ", ".join(absent))


def construct(adapter, dossier, case, owned=None, *, spawn_adjust_m=0.0):
    """Configure one exact case; all structure, vehicle and sign facts read back."""
    require_adapter(adapter)
    site = validate_site(dossier, expected_case=case["case_id"])
    if adapter.loaded_map_sha256() != dossier["map_opendrive_sha256"]:
        raise ValueError("loaded original OpenDRIVE differs from reviewed site")
    mapped = adapter.read_structure_ends(dossier["structure_id"])
    if mapped != (site["end_a_station_m"], site["end_b_station_m"]):
        raise ValueError("mapped original elevated-structure ends differ")
    direction = case["travel_direction_request"]
    if dossier["travel_direction"] != direction:
        raise ValueError("reviewed site and exact approach direction differ")
    if dossier["structure_kind"] != case["structure_kind_request"]:
        raise ValueError("reviewed structure kind differs from exact case")
    if owned is None:
        owned = []
    if not isinstance(spawn_adjust_m, (int, float)) or not 0 <= spawn_adjust_m <= 5:
        raise ValueError("bounded engineering spawn adjustment required")
    ego = adapter.spawn_vehicle("motor_vehicle", direction, dossier["structure_id"],
                                spawn_adjust_m=spawn_adjust_m)
    owned.append(ego)
    if adapter.read_vehicle_class(ego) != "motor_vehicle":
        raise ValueError("conventional motor vehicle readback required")
    adapter.set_crossing_route(ego, direction, site["end_a_station_m"], site["end_b_station_m"])
    requested_mph = site["declared_maximum_mph"] + case["requested_speed_delta_from_declared_maximum_mph"]
    if requested_mph <= 0:
        raise ValueError("nonpositive requested crossing speed")
    adapter.set_target_speed_mps(ego, requested_mph / 2.2369362920544)
    signs = {}
    for end in ("end_a", "end_b"):
        sign_source = dossier["signs"][end]
        sign = adapter.spawn_sign(end, sign_source["station_m"], site["declared_maximum_mph"],
                                  sign_source["face_direction"])
        owned.append(sign)
        station, face = adapter.read_sign_station_and_face(sign)
        if station != sign_source["station_m"] or face != sign_source["face_direction"]:
            raise ValueError("original spawned sign station/face readback differs")
        signs[end] = sign
    cameras = adapter.spawn_cameras(ego, CAMERAS, dossier)
    if not isinstance(cameras, dict) or set(cameras) != set(CAMERAS) or any(
            camera is None for camera in cameras.values()):
        raise ValueError("four synchronized original camera actors required")
    owned.extend(cameras[name] for name in CAMERAS)
    return {"ego": ego, "signs": signs, "cameras": cameras, "owned": owned,
            "requested_speed_mph": requested_mph,
            "sign_offsets_ft": site["sign_offsets_ft"]}


def destroy_owned(adapter, actors, original_settings):
    destroyed = []
    failures = []
    for actor in reversed(actors):
        try:
            adapter.destroy(actor)
            destroyed.append(adapter.actor_id(actor))
        except Exception as error:
            failures.append(str(error))
    try:
        adapter.restore_settings(original_settings)
        if adapter.readback_restored(original_settings) is not True:
            failures.append("original world settings not restored")
    except Exception as error:
        failures.append(str(error))
    if failures:
        raise ValueError("Native owner cleanup failed: " + "; ".join(failures))
    return destroyed

"""Saved original-source measurements for an exact NRS 484B.633(2) case."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from bridge_observations import measure_crossing, verify_site_bundle


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def structure_crossing_observation(measured, site):
    return {key: measured[key] for key in (
        "structure_kind", "direction", "crossing_original_frames", "original_frame_count")}


def crossing_speed_observation(measured, site):
    return {"declared_maximum_mph": measured["declared_maximum_mph"],
            "observed_crossing_speed_mph": measured["observed_crossing_speed_mph"],
            "structure_safety_judgment": "unresolved"}


def both_signs_observation(measured, site):
    return {"sign_offsets_ft": measured["sign_offsets_ft"],
            "sign_placement_judgment": "unresolved"}


def department_authority_observation(measured, site):
    return {"source_refs": site["authority"],
            "maximum_declaration_source": site["maximum_declaration_source"],
            "sign_causation_judgment": "unresolved"}


def original_capture_observation(measured, site):
    return {"original_frame_count": measured["original_frame_count"],
            "physical_completion": "requires_independent_original_review"}


def build_report(attempt: Path, case_id: str) -> dict:
    attempt = Path(attempt)
    receipt = attempt / "original-source-receipt.json"
    if not receipt.is_file():
        raise ValueError("Missing required source: original-source-receipt.json")
    receipt_data = json.loads(receipt.read_text(encoding="utf-8"))
    if receipt_data.get("case_id") != case_id:
        raise ValueError("original source receipt case differs")
    site_path = attempt / "bridge-site.json"
    trace_path = attempt / "original-motion.jsonl"
    if not site_path.is_file():
        raise ValueError("Missing required source: bridge-site.json")
    if not trace_path.is_file():
        raise ValueError("Missing required source: original-motion.jsonl")
    if receipt_data.get("site_sha256") != sha(site_path) or receipt_data.get("trace_sha256") != sha(trace_path):
        raise ValueError("original source receipt hash differs")
    site = verify_site_bundle(site_path, receipt_data["site_sha256"], case_id)
    rows = [json.loads(line) for line in trace_path.read_text(encoding="utf-8").splitlines()]
    marker = attempt / "fixture-provenance.json"
    diagnostic = marker.is_file() and json.loads(marker.read_text()).get("scope", "").startswith("CPU diagnostic")
    expected = 9 if diagnostic else 900
    if bool(receipt_data.get("diagnostic_fixture", False)) != diagnostic:
        raise ValueError("diagnostic source provenance marker differs")
    measured = measure_crossing(site, rows, case_id, expected_frames=expected)
    sources = {"original-source-receipt.json": sha(receipt),
               "bridge-site.json": sha(site_path),
               "original-motion.jsonl": sha(trace_path)}
    methods = (structure_crossing_observation, crossing_speed_observation,
               both_signs_observation, department_authority_observation,
               original_capture_observation)
    return {
        "format": "worker-analysis-report", "case_id": case_id,
        "analysis_complete": True, "legal_verdict_claimed": False,
        "diagnostic_fixture": diagnostic,
        "measurements": {method.__name__: {
            "value": method(measured, site), "method": method.__name__, "sources": sources}
            for method in methods},
    }


def saved_result(attempt: Path, report: dict) -> dict:
    """Build Native-shaped saved evidence without assigning a legal verdict."""
    from worker_exchange.native_output import physical_result, validate_result

    attempt = Path(attempt)
    config = json.loads((attempt / "config.json").read_text(encoding="utf-8"))
    description = config["case"]["recording_description"]
    trace = [json.loads(line) for line in (attempt / "original-motion.jsonl").read_text().splitlines()]
    channels = attempt / "channels"
    channels.mkdir(exist_ok=True)
    evidence = []
    for channel in description["channels"]:
        name = channel["name"]
        path = channels / (name + ".jsonl")
        with path.open("x", encoding="utf-8") as stream:
            for row in trace:
                if name == "four_camera_pixels":
                    value = {"frame": row["original_frame"],
                             "views": ["overview", "approach", "reference_corner", "driver_reference"]}
                else:
                    value = row[name]
                stream.write(json.dumps({"time_s": row["time_s"], "value": value}) + "\n")
        evidence.append({"name": name, "unit": channel["unit"],
                         "reference": str(path.relative_to(attempt))})
    context_path = channels / "site-context.json"
    site = json.loads((attempt / "bridge-site.json").read_text())
    context_path.write_text(json.dumps({
        "elevated_structure_ends": [site["end_a_station_m"], site["end_b_station_m"]],
        "declared_structural_maximum": site["declared_maximum_mph"],
        "both_sign_stations": {end: sign["station_m"] for end, sign in site["signs"].items()},
        "department_authority_and_chronology": site["authority"],
        "site_sha256": sha(attempt / "bridge-site.json"),
        "original_source_receipt_sha256": sha(attempt / "original-source-receipt.json"),
        "independent_physical_and_legal_review": "pending"}, sort_keys=True) + "\n")
    for item in description["context_inputs"]:
        evidence.append({"name": item["name"], "unit": item["unit"],
                         "reference": "channels/site-context.json"})
    measured = report["measurements"]["crossing_speed_observation"]["value"]
    requested = measured["declared_maximum_mph"] + config["case"]["requested_speed_delta_from_declared_maximum_mph"]
    observed = measured["observed_crossing_speed_mph"]["maximum"]
    result = {
        "case_id": report["case_id"], "measured_values": report["measurements"],
        "target_checks": [{"target": "authored engineering crossing speed maximum",
                           "requested": requested, "measured": observed,
                           "method": "original source-joined crossing speed samples",
                           "tolerance": 5.0, "matched": abs(requested - observed) <= 5,
                           "physical_cause_confirmed": False,
                           "cause_evidence": {"original-motion.jsonl": sha(attempt / "original-motion.jsonl")}}],
        "setup_confirmed": False, "behavior_attempted": False, "maneuver_completed": False,
        "termination_reason": "Saved-only source measurement; physical and legal review pending",
        "physical_failure_flags": [], "trace_reference": "trace.jsonl",
        "video_references": ["overview.mkv", "approach.mkv", "reference_corner.mkv", "driver_reference.mkv"],
        "video_frame_map_reference": "video_frames.jsonl",
        "recording_description": description, "recording_evidence": evidence,
        "realized_observables": {},
    }
    result = physical_result(attempt, result)
    validate_result(result)
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True, type=Path)
    parser.add_argument("--case")
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    case_id = args.case
    if case_id is None:
        case_id = json.loads((args.attempt / "config.json").read_text(encoding="utf-8"))["selected_case_id"]
    if args.output.exists():
        raise ValueError("fresh analysis output required")
    report = build_report(args.attempt, case_id)
    result = saved_result(args.attempt, report)
    (args.attempt / "result.json").write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")
    report["physical_checks"] = result["physical_checks"]
    report["realized_observables"] = result["realized_observables"]
    args.output.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

